#!/bin/bash
# Uninstall script for Unsloth Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Unsloth Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Unsloth Desktop if running..."
pkill -f "Unsloth Desktop" 2>/dev/null || true

# Remove /Applications/Unsloth.app
echo "Removing /Applications/Unsloth.app..."
if [ -d "/Applications/Unsloth.app" ]; then
    rm -rf "/Applications/Unsloth.app" 2>/dev/null || true
elif [ -f "/Applications/Unsloth.app" ]; then
    rm -f "/Applications/Unsloth.app" 2>/dev/null || true
fi

# Remove $HOME/.unsloth/studio
echo "Removing $HOME/.unsloth/studio..."
if [ -d "$HOME/.unsloth/studio" ]; then
    rm -rf "$HOME/.unsloth/studio" 2>/dev/null || true
elif [ -f "$HOME/.unsloth/studio" ]; then
    rm -f "$HOME/.unsloth/studio" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/ai.unsloth.studio
echo "Removing $HOME/Library/Application Support/ai.unsloth.studio..."
if [ -d "$HOME/Library/Application Support/ai.unsloth.studio" ]; then
    rm -rf "$HOME/Library/Application Support/ai.unsloth.studio" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/ai.unsloth.studio" ]; then
    rm -f "$HOME/Library/Application Support/ai.unsloth.studio" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/ai.unsloth.studio
echo "Removing $HOME/Library/Caches/ai.unsloth.studio..."
if [ -d "$HOME/Library/Caches/ai.unsloth.studio" ]; then
    rm -rf "$HOME/Library/Caches/ai.unsloth.studio" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/ai.unsloth.studio" ]; then
    rm -f "$HOME/Library/Caches/ai.unsloth.studio" 2>/dev/null || true
fi

# Remove $HOME/Library/LaunchAgents/unsloth-studio.plist
echo "Removing $HOME/Library/LaunchAgents/unsloth-studio.plist..."
if [ -d "$HOME/Library/LaunchAgents/unsloth-studio.plist" ]; then
    rm -rf "$HOME/Library/LaunchAgents/unsloth-studio.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/LaunchAgents/unsloth-studio.plist" ]; then
    rm -f "$HOME/Library/LaunchAgents/unsloth-studio.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/WebKit/ai.unsloth.studio
echo "Removing $HOME/Library/WebKit/ai.unsloth.studio..."
if [ -d "$HOME/Library/WebKit/ai.unsloth.studio" ]; then
    rm -rf "$HOME/Library/WebKit/ai.unsloth.studio" 2>/dev/null || true
elif [ -f "$HOME/Library/WebKit/ai.unsloth.studio" ]; then
    rm -f "$HOME/Library/WebKit/ai.unsloth.studio" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
